/**
 * Embedding parity tests: the TypeScript canonical pipeline +
 * onnxruntime-node must reproduce the committed Python reference vectors
 * (generated by scripts/semantic-corpus/reference-embeddings.py with the
 * official onnxruntime Python build — an independent runtime).
 *
 * These tests are skipped when the model weights are not present. Fetch
 * them with scripts/semantic-corpus/fetch-models.sh into
 * $VARVE_MODEL_CACHE (default ~/.cache/varve/models) and regenerate
 * fixtures with the reference script when the corpus changes.
 */

import { readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { afterAll, describe, expect, it } from 'vitest';
import { cosineSimilarity } from '../../inference/models/siglip';
import { loadCorpusManifest } from './corpus';
import { makeDinov2Adapter, makeSiglipAdapter } from './models';
import { releaseNodeOrtSessions } from './ortNode';

const FIXTURE_DIR = resolve(__dirname, '__fixtures__/reference');
const MODELS_DIR = resolve(
  process.env.VARVE_MODEL_CACHE ?? join(process.env.HOME ?? '/tmp', '.cache/varve/models'),
);

interface ReferenceFixture {
  modelId: string;
  runtime: string;
  images: Record<string, { base64: string }>;
}

function loadFixture(modelId: string): ReferenceFixture | null {
  try {
    return JSON.parse(
      readFileSync(join(FIXTURE_DIR, `${modelId}.json`), 'utf-8'),
    ) as ReferenceFixture;
  } catch {
    return null;
  }
}

function decodeBase64Vector(base64: string): Float32Array {
  const bytes = Buffer.from(base64, 'base64');
  const arr = new Float32Array(bytes.byteLength / 4);
  new Uint8Array(arr.buffer).set(bytes);
  return arr;
}

function modelPresent(modelId: string): boolean {
  const file =
    modelId === 'siglip-base-patch16-224' ? 'siglip-base-patch16-224.onnx' : 'dinov2-small.onnx';
  try {
    readFileSync(join(MODELS_DIR, file));
    return true;
  } catch {
    return false;
  }
}

const runParity = (modelId: string, tolerance: number) => {
  const fixture = loadFixture(modelId);
  const available = fixture && modelPresent(modelId);
  if (!fixture) return;
  if (!available) {
    describe.skip(`${modelId} parity (weights not present)`, () => {
      it('skipped', () => expect(true).toBe(true));
    });
    return;
  }

  // Sample a deterministic subset of the fixture that still covers every
  // preprocessing geometry: landscape base/variants (img-000..003) and
  // portrait base/variants (img-019, 020, 026, 027 — the half-pixel
  // letterbox-offset case that regressed banker's-rounding ports). The
  // full 24-vector fixture stays committed for manual review; running all
  // 24 through both models takes ~15 minutes on CPU-only CI machines.
  const fixtureImages = Object.keys(fixture.images)
    .sort()
    .filter((id) => /^img-(000|001|002|003|019|020|026|027)$/.test(id));
  if (fixtureImages.length !== 8) throw new Error('Unexpected parity fixture sample');
  const adapter =
    modelId === 'siglip-base-patch16-224'
      ? makeSiglipAdapter(join(MODELS_DIR, 'siglip-base-patch16-224.onnx'))
      : makeDinov2Adapter(join(MODELS_DIR, 'dinov2-small.onnx'));

  describe(`${modelId} parity vs python onnxruntime ${fixture.runtime}`, () => {
    it('reproduces the reference vectors within tolerance', { timeout: 600_000 }, async () => {
      const corpus = loadCorpusManifest();
      let maxCosineError = 0;
      let maxAbsDiff = 0;
      for (const id of fixtureImages) {
        const image = corpus.byId.get(id);
        if (!image) continue;
        const { decodeRgba } = await import('./corpus');
        const buf = readFileSync(join(corpus.root, image.file));
        const decoded = decodeRgba(buf);
        const vector = await adapter.embed(decoded.data, decoded.width, decoded.height);
        const reference = decodeBase64Vector(fixture.images[id]!.base64);
        expect(vector.length).toBe(reference.length);
        const cos = cosineSimilarity(vector, reference);
        maxCosineError = Math.max(maxCosineError, 1 - cos);
        for (let i = 0; i < vector.length; i++) {
          maxAbsDiff = Math.max(maxAbsDiff, Math.abs(vector[i]! - reference[i]!));
        }
      }
      // Report measured parity even on success (useful for tolerance drift).
      console.log(
        `[parity:${modelId}] max 1-cos=${maxCosineError.toExponential(3)} maxAbs=${maxAbsDiff.toExponential(3)}`,
      );
      expect(maxCosineError).toBeLessThan(tolerance);
    });

    it('is deterministic across session instances', { timeout: 120_000 }, async () => {
      const corpus = loadCorpusManifest();
      const image = corpus.byId.get(fixtureImages[0]!);
      if (!image) return;
      const { decodeRgba } = await import('./corpus');
      const buf = readFileSync(join(corpus.root, image.file));
      const decoded = decodeRgba(buf);
      const v1 = await adapter.embed(decoded.data, decoded.width, decoded.height);
      const v2 = await adapter.embed(decoded.data, decoded.width, decoded.height);
      expect(cosineSimilarity(v1, v2)).toBeGreaterThan(1 - 1e-6);
    });
  });
};

runParity('siglip-base-patch16-224', 1e-4);
runParity('dinov2-small', 1e-5);

afterAll(async () => {
  await releaseNodeOrtSessions();
});
